use std::fs

fn find(ks: Vec<int>, k: int) -> int {
    let mut i = 0
    while i < ks.len() as int {
        if ks[i as usize] == k { return i }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut lines = text.lines()
    let cap: int = lines.next().unwrap_or("1").trim().parse().unwrap_or(1)
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines().skip(1) {
        let parts = line.split_whitespace().map(|s| s.to_string()).collect::<Vec<string>>()
        if parts.len() == 0 { continue }
        let cmd = parts[0].clone()
        if cmd == "put" {
            let k: int = parts[1].parse().unwrap_or(0)
            let v: int = parts[2].parse().unwrap_or(0)
            let i = find(ks.clone(), k)
            if i >= 0 {
                ks.remove(i as usize)
                vs.remove(i as usize)
            }
            ks.insert(0, k)
            vs.insert(0, v)
            if ks.len() as int > cap {
                let last = ks.len() - 1
                let e = ks[last]
                ks.remove(last)
                vs.remove(last)
                println("evict ${e}")
            }
        } else if cmd == "get" {
            let k: int = parts[1].parse().unwrap_or(0)
            let i = find(ks.clone(), k)
            if i < 0 {
                println("-1")
            } else {
                let v = vs[i as usize]
                ks.remove(i as usize)
                vs.remove(i as usize)
                ks.insert(0, k)
                vs.insert(0, v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut first = true
                for k in ks.clone() {
                    if !first { out = out + " " }
                    first = false
                    out = out + "${k}"
                }
                println("${out}")
            }
        }
    }
}

